mapper.sql:
FROM code a
JOIN codegroup b ON b.ifcgseq = a.codegroup_ifcgseq
WHERE 1=1
	AND a.ifcddelNy = 0

	 	AND a.ifcduseNy = #{shUseNy}
        AND a.ifcddelNy = #{shDelNy}


            AND a.ifcdseq = #{shValue}
            AND a.ifcdname LIKE CONCAT('%',#{shValue},'%')
            AND a.ifcdcodename LIKE CONCAT('%',#{shValue},'%')
